<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><form class="editor" method="post" action="<?= site_url('admin/pages/save') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= esc($page['id'] ?? '') ?>"><div class="editor-main"><label>Page title<input name="title" value="<?= esc(old('title', $page['title'] ?? '')) ?>" required></label><label>URL slug<input name="slug" value="<?= esc(old('slug', $page['slug'] ?? '')) ?>" required></label><label>Short introduction<textarea name="excerpt" rows="3"><?= esc(old('excerpt', $page['excerpt'] ?? '')) ?></textarea></label><label>Page content <small>HTML is supported for trusted editors.</small><textarea class="rich" name="body" rows="18"><?= esc(old('body', $page['body'] ?? '')) ?></textarea></label></div><aside class="editor-side"><h2>Publishing</h2><label>Status<select name="status"><option value="draft" <?= old('status', $page['status'] ?? '') === 'draft' ? 'selected' : '' ?>>Draft</option><option value="published" <?= old('status', $page['status'] ?? '') === 'published' ? 'selected' : '' ?>>Published</option></select></label><label>Hero image path<input name="hero_image" value="<?= esc(old('hero_image', $page['hero_image'] ?? '')) ?>" placeholder="uploads/image.jpg"></label><label>SEO title<input name="seo_title" value="<?= esc(old('seo_title', $page['seo_title'] ?? '')) ?>"></label><label>SEO description<textarea name="seo_description" rows="3"><?= esc(old('seo_description', $page['seo_description'] ?? '')) ?></textarea></label><button class="admin-button">Save page</button><a href="<?= site_url('admin/pages') ?>">Cancel</a></aside></form><?= $this->endSection() ?>
